function tarRoll(){var $el,leftPos,newWidth;var $magicLine=$("#magic-line");var currentItem=$(".current_page_item");if(currentItem.length===0){return}var lineWidth=parseInt(currentItem.width()*0.5);var currentLink=currentItem.find("a");if(currentLink.length===0){return}var linkPosition=currentLink.position();if(!linkPosition){return}var lineLeft=parseFloat(linkPosition.left+currentItem.width()*0.17);$magicLine.width(lineWidth).css("left",lineLeft).data("origLeft",$magicLine.position().left).data("origWidth",$magicLine.width());$("#example-one li").find("a").hover(function(){$el=$(this);leftPos=parseFloat($el.position().left+$el.parent().width()*0.17);newWidth=parseInt($el.parent().width()*0.5);$magicLine.stop().animate({left:leftPos,width:newWidth})},function(){$magicLine.stop().animate({left:$magicLine.data("origLeft"),width:$magicLine.data("origWidth")})})}var winHeight=document.documentElement.clientHeight;var winWidth=document.documentElement.clientWidth;$(function(){$("#example-one").append("<li id='magic-line'></li>");tarRoll()});$(window).resize(function(){if(winWidth>414){tarRoll()}});